import {PGlite} from '@electric-sql/pglite'
const baseline={"sourceSchemaSHA256":"c4e86b3bda8dc8579df1b3bfa9bdc8994b9ca0085c07710c36a15e1259069823","functions":{"gridex_ediel_retention.decision_evidence_basis_v1":"CREATE FUNCTION gridex_ediel_retention.decision_evidence_basis_v1(c uuid, k text, target uuid) RETURNS jsonb\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $_$DECLARE tab text;r jsonb;bytes bytea;BEGIN\n IF k IN('life_event_classification_source_original_bytes','life_event_classification_receipt_original_bytes','life_event_classification_revocation_original_bytes') THEN RETURN gridex_ediel_retention.classification_copy_basis_v1(c,k,target);END IF; IF k IN('masterdata_declaration_agreement_original_bytes','masterdata_declaration_source_original_bytes','masterdata_preparation_agreement_original_bytes','masterdata_preparation_source_original_bytes','metering_contract_request_agreement_original_bytes','metering_contract_request_source_original_bytes','metering_method_event_agreement_original_bytes','metering_method_event_source_original_bytes') THEN RETURN gridex_ediel_retention.contract_copy_basis_v1(c,k,target);END IF; IF EXISTS(SELECT FROM gridex_ediel_retention.protected_copy_specs WHERE retention_class=k) THEN RETURN gridex_ediel_retention.protected_copy_basis_v1(c,k,target);END IF; SELECT source_table INTO STRICT tab FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=k;\n EXECUTE format('SELECT to_jsonb(d),d.document_bytes FROM gridex_ediel_retention.%I d WHERE id=$1 AND company_id=$2 FOR UPDATE',tab) INTO r,bytes USING target,c;\n IF r IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;\n IF bytes IS NULL OR octet_length(bytes) NOT BETWEEN 1 AND 1048576 OR encode(sha256(bytes),'hex') IS DISTINCT FROM r->>'document_hash' THEN RAISE EXCEPTION 'decision_evidence_actual_original_bytes_required';END IF;\n RETURN jsonb_build_object('retentionClass',k,'targetId',target,'sourceHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'byteLength',octet_length(bytes));\nEND$_$;","gridex_ediel_retention.decision_evidence_receipt_v1":"CREATE FUNCTION gridex_ediel_retention.decision_evidence_receipt_v1(d gridex_ediel_retention.decision_evidence_policies) RETURNS jsonb\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $_$DECLARE issuer gridex_ediel_retention.issuers%rowtype;p jsonb;bytes bytea;issued timestamptz;expires timestamptz;deadline timestamptz;journal_end timestamptz;BEGIN\n IF d.document_bytes IS NULL OR encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash OR jsonb_typeof(d.issuer_receipt) IS DISTINCT FROM 'object' OR coalesce(d.issuer_receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(d.issuer_receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN NULL;END IF;\n SELECT * INTO issuer FROM gridex_ediel_retention.issuers WHERE id=(d.issuer_receipt->>'issuerId')::uuid AND company_id=d.company_id FOR SHARE;\n IF issuer.id IS NULL OR encode(sha256(issuer.legal_evidence),'hex') IS DISTINCT FROM issuer.legal_hash OR clock_timestamp()<issuer.valid_from OR clock_timestamp()>=issuer.valid_to OR EXISTS(SELECT FROM gridex_ediel_retention.issuer_revocations WHERE issuer_id=issuer.id) OR EXISTS(SELECT FROM gridex_ediel_retention.decision_evidence_revocations WHERE policy_id=d.id) THEN RETURN NULL;END IF;\n bytes:=decode(d.issuer_receipt->>'payloadBase64','base64');IF encode(gridex_requested_changes.receipt_hmac_sha256_v1(bytes,issuer.signing_key),'hex') IS DISTINCT FROM d.issuer_receipt->>'signatureHex' THEN RETURN NULL;END IF;\n p:=convert_from(bytes,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;deadline:=(p->>'retainUntil')::timestamptz;journal_end:=(p->>'journalRetainUntil')::timestamptz;\n IF p->>'format' IS DISTINCT FROM 'ediel_retention_decision_original_policy_v1' OR p->>'operation' IS DISTINCT FROM 'erase_retention_decision_original_bytes' OR p->>'retentionClass' IS DISTINCT FROM d.retention_class OR p->>'companyId' IS DISTINCT FROM d.company_id::text OR p->>'targetId' IS DISTINCT FROM d.target_id::text OR p->>'sourceHash' IS DISTINCT FROM d.source_hash OR p->>'targetMetadataHash' IS DISTINCT FROM d.target_metadata_hash OR p->>'documentHash' IS DISTINCT FROM d.document_hash OR p->>'issuerLegalReference' IS DISTINCT FROM issuer.legal_reference OR nullif(btrim(p->>'legalBasisReference'),'') IS NULL OR nullif(btrim(p->>'journalPurposeReference'),'') IS NULL OR isfinite(issued) IS DISTINCT FROM true OR isfinite(expires) IS DISTINCT FROM true OR isfinite(deadline) IS DISTINCT FROM true OR isfinite(journal_end) IS DISTINCT FROM true OR issued>clock_timestamp() OR expires<=clock_timestamp() OR issued<issuer.valid_from OR expires>issuer.valid_to OR journal_end<=clock_timestamp() OR journal_end<deadline THEN RETURN NULL;END IF;\n RETURN p;\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN NULL;\nEND$_$;","gridex_ediel_retention.permission_v1":"CREATE FUNCTION gridex_ediel_retention.permission_v1(c uuid, actor uuid, wanted text) RETURNS boolean\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $$\nDECLARE retention_keys constant text[]:=ARRAY['ediel.retention.submit','ediel.retention.review','ediel.retention.purge','ediel.retention.source_bytes','ediel.retention.customer_fields','ediel.retention.original_bytes','ediel.retention.mime_bytes','ediel.retention.artifact_decision_evidence','ediel.retention.blob_decision_evidence','ediel.retention.record_decision_evidence','ediel.retention.process_decision_evidence','ediel.retention.decision_policy_evidence','ediel.retention.billing_source_evidence','ediel.retention.invoice_copy_evidence','ediel.retention.settlement_copy_evidence','ediel.retention.finance_decision_evidence'];\nretention_grant_observed_at timestamptz;\nBEGIN\n IF wanted<>ALL(retention_keys) THEN RETURN gridex_requested_changes.scoped_permission_v1(c,actor,wanted) IS TRUE\n AND NOT EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND (u.company_id=c OR u.company_id IS NULL) AND u.is_active AND u.status='active' AND u.effect='deny' AND p.key=wanted)\n AND NOT EXISTS(SELECT FROM public.user_permission_overrides o WHERE o.user_id=actor AND (o.company_id=c OR o.company_id IS NULL) AND o.is_active AND o.effect='deny' AND o.permission_key=wanted)\n AND public.gridex_actor_has_company_permission(actor,c,wanted) IS TRUE;END IF;\n IF NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status IN('active','archived','pending_deletion','closed'))\n  OR NOT public.ediel_retention_lock_auth_actor_v1(actor)\n  OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')\n  OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL) THEN RETURN false;END IF;\n retention_grant_observed_at:=clock_timestamp();\n IF NOT EXISTS(SELECT FROM public.permissions WHERE key=wanted AND is_active)\n  OR EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND (u.company_id=c OR u.company_id IS NULL) AND u.is_active AND u.status='active' AND u.effect='deny' AND p.key=wanted)\n  OR EXISTS(SELECT FROM public.user_permission_overrides o WHERE o.user_id=actor AND (o.company_id=c OR o.company_id IS NULL) AND o.is_active AND o.effect='deny' AND o.permission_key=wanted AND (o.valid_from IS NULL OR o.valid_from<=retention_grant_observed_at) AND (o.valid_to IS NULL OR retention_grant_observed_at<o.valid_to))\n  OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND (u.company_id=c OR u.company_id IS NULL) AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='deny' AND p.key=wanted) THEN RETURN false;END IF;\n RETURN EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key=wanted)\n  OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key=wanted)\n  OR EXISTS(SELECT FROM public.user_permission_overrides o WHERE o.user_id=actor AND o.company_id=c AND o.is_active AND o.effect='allow' AND o.permission_key=wanted AND (o.valid_from IS NULL OR o.valid_from<=retention_grant_observed_at) AND (o.valid_to IS NULL OR retention_grant_observed_at<o.valid_to));\nEND$$;","public.ediel_current_retention_session_v1":"CREATE FUNCTION public.ediel_current_retention_session_v1(p_company_id uuid, p_actor_user_id uuid) RETURNS jsonb\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $$\nDECLARE wanted text;own_class text;allowed text[]:=ARRAY[]::text[];BEGIN\n LOCK TABLE public.permissions,public.roles,public.user_roles,public.role_permissions,public.user_permissions,public.user_permission_overrides IN SHARE MODE;\n PERFORM public.ediel_retention_lock_auth_actor_v1(p_actor_user_id);PERFORM id FROM public.user_profiles WHERE id=p_actor_user_id FOR SHARE;PERFORM id FROM public.companies WHERE id=p_company_id FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=p_company_id AND user_id=p_actor_user_id FOR SHARE;\n IF public.ediel_retention_session_actor_v1() IS DISTINCT FROM p_actor_user_id THEN RAISE EXCEPTION 'retention_current_session_actor_required' USING ERRCODE='42501';END IF;\n FOREACH wanted IN ARRAY ARRAY['ediel.retention.read','ediel.retention.submit','ediel.retention.review','ediel.retention.purge','ediel.retention.source_bytes','ediel.retention.customer_fields','ediel.retention.original_bytes','ediel.retention.mime_bytes','ediel.retention.contract_pdf','ediel.retention.signature','ediel.retention.address_history','ediel.retention.portal_history','ediel.retention.legal_history','ediel.retention.artifact_decision_evidence','ediel.retention.blob_decision_evidence','ediel.retention.record_decision_evidence','ediel.retention.process_decision_evidence','ediel.retention.decision_policy_evidence','ediel.retention.billing_source_evidence','ediel.retention.invoice_copy_evidence','ediel.retention.settlement_copy_evidence','ediel.retention.finance_decision_evidence'] LOOP\n  SELECT retention_class INTO own_class FROM gridex_ediel_retention.record_class_catalog WHERE permission_key=wanted ORDER BY retention_class LIMIT 1;IF wanted='ediel.retention.read' THEN own_class:='__read_scope__';END IF;\n  IF (own_class IS NOT NULL AND gridex_ediel_retention.record_permission_v1(p_company_id,p_actor_user_id,own_class) IS TRUE) OR (own_class IS NULL AND gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,wanted) IS TRUE) THEN allowed:=array_append(allowed,wanted);END IF;\n END LOOP;\n IF NOT allowed&&ARRAY['ediel.retention.read','ediel.retention.submit','ediel.retention.review','ediel.retention.purge'] OR NOT allowed&&ARRAY['ediel.retention.source_bytes','ediel.retention.customer_fields','ediel.retention.original_bytes','ediel.retention.mime_bytes','ediel.retention.contract_pdf','ediel.retention.signature','ediel.retention.address_history','ediel.retention.portal_history','ediel.retention.legal_history','ediel.retention.artifact_decision_evidence','ediel.retention.blob_decision_evidence','ediel.retention.record_decision_evidence','ediel.retention.process_decision_evidence','ediel.retention.decision_policy_evidence','ediel.retention.billing_source_evidence','ediel.retention.invoice_copy_evidence','ediel.retention.settlement_copy_evidence','ediel.retention.finance_decision_evidence'] THEN RAISE EXCEPTION 'retention_current_explicit_session_required' USING ERRCODE='42501';END IF;\n RETURN jsonb_build_object('companyId',p_company_id,'actorUserId',p_actor_user_id,'permissions',allowed);\nEND$$;","public.ediel_purge_decision_evidence_retention_v1":"CREATE FUNCTION public.ediel_purge_decision_evidence_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_policy_id uuid) RETURNS jsonb\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $_$DECLARE d gridex_ediel_retention.decision_evidence_policies%rowtype;r gridex_ediel_retention.decision_evidence_reviews%rowtype;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;spec gridex_ediel_retention.decision_evidence_catalog%rowtype;p jsonb;basis jsonb;at timestamptz:=clock_timestamp();BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();\n PERFORM gridex_ediel_retention.decision_evidence_lock_v1(p_company_id);\n SELECT * INTO STRICT d FROM gridex_ediel_retention.decision_evidence_policies WHERE id=p_policy_id AND company_id=p_company_id FOR UPDATE;PERFORM gridex_ediel_retention.decision_evidence_actor_v1(p_company_id,p_actor_user_id,d.retention_class,'ediel.retention.purge');\n SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=d.retention_class AND target_id=d.target_id;\n IF FOUND THEN IF t.policy_id IS DISTINCT FROM d.id OR t.company_id IS DISTINCT FROM p_company_id THEN RAISE EXCEPTION 'decision_original_purge_replay_conflict';END IF;RETURN jsonb_build_object('status','purged','retentionClass',d.retention_class,'targetId',d.target_id,'sourceHash',t.source_hash,'byteLength',t.byte_length,'bytesAvailable',false,'authority','none','replay',true);END IF;\n SELECT * INTO r FROM gridex_ediel_retention.decision_evidence_reviews WHERE policy_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;\n IF r.outcome IS DISTINCT FROM 'approved' OR r.actor_user_id=d.submitted_by THEN RETURN jsonb_build_object('status','held','policyId',d.id,'missing',ARRAY['separate_current_original_class_review']);END IF;\n PERFORM gridex_ediel_retention.decision_evidence_lock_reviewer_v1(p_company_id,r.actor_user_id,d.retention_class);p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);\n IF p IS NULL OR (p->>'retainUntil')::timestamptz>at THEN RETURN jsonb_build_object('status','held','policyId',d.id,'missing',ARRAY['current_exact_original_deadline']);END IF;\n basis:=gridex_ediel_retention.decision_evidence_basis_v1(p_company_id,d.retention_class,d.target_id);IF basis->>'sourceHash' IS DISTINCT FROM d.source_hash OR basis->>'targetMetadataHash' IS DISTINCT FROM d.target_metadata_hash THEN RETURN jsonb_build_object('status','held','policyId',d.id,'missing',ARRAY['unchanged_original_source_metadata']);END IF;\n SELECT * INTO STRICT spec FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=d.retention_class;\n PERFORM gridex_ediel_retention.decision_evidence_actor_v1(p_company_id,p_actor_user_id,d.retention_class,'ediel.retention.purge');\n PERFORM gridex_ediel_retention.decision_evidence_lock_reviewer_v1(p_company_id,r.actor_user_id,d.retention_class);\n p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);\n PERFORM gridex_ediel_retention.decision_evidence_actor_v1(p_company_id,p_actor_user_id,d.retention_class,'ediel.retention.purge');\n PERFORM gridex_ediel_retention.decision_evidence_lock_reviewer_v1(p_company_id,r.actor_user_id,d.retention_class);\n at:=clock_timestamp();IF p IS NULL OR (p->>'retainUntil')::timestamptz>at THEN RETURN jsonb_build_object('status','held','policyId',d.id,'missing',ARRAY['current_exact_original_deadline']);END IF;\n -- Invalidate the consumed original policy before physical byte removal. Its\n -- already completed receipts remain available as immutable historical facts.\n IF d.retention_class IN('masterdata_declaration_agreement_original_bytes','masterdata_declaration_source_original_bytes','masterdata_preparation_agreement_original_bytes','masterdata_preparation_source_original_bytes','metering_contract_request_agreement_original_bytes','metering_contract_request_source_original_bytes','metering_method_event_agreement_original_bytes','metering_method_event_source_original_bytes') THEN INSERT INTO gridex_ediel_retention.contract_copy_revocations(retention_class,target_id,company_id,policy_id,review_id,source_hash,actor_user_id) VALUES(d.retention_class,d.target_id,d.company_id,d.id,r.id,d.source_hash,p_actor_user_id);ELSIF d.retention_class IN('life_event_classification_source_original_bytes','life_event_classification_receipt_original_bytes','life_event_classification_revocation_original_bytes') THEN INSERT INTO gridex_ediel_retention.classification_copy_revocations(retention_class,classification_id,company_id,source_message_id,policy_id,review_id,source_hash,actor_user_id) SELECT d.retention_class,d.target_id,d.company_id,q.source_message_id,d.id,r.id,d.source_hash,p_actor_user_id FROM gridex_customer_life_events.inbound_classifications q WHERE q.id=d.target_id AND q.company_id=d.company_id;ELSE IF EXISTS(SELECT FROM gridex_ediel_retention.protected_copy_specs WHERE retention_class=d.retention_class) THEN INSERT INTO gridex_ediel_retention.protected_copy_revocations(retention_class,target_id,company_id,policy_id,review_id,source_hash,actor_user_id) VALUES(d.retention_class,d.target_id,d.company_id,d.id,r.id,d.source_hash,p_actor_user_id);ELSE EXECUTE format('INSERT INTO gridex_ediel_retention.%I(%I,actor_user_id,reason) VALUES($1,$2,$3) ON CONFLICT DO NOTHING',spec.revocation_table,spec.revocation_id_column) USING d.target_id,p_actor_user_id,left('Qualified decision-original policy: '||(p->>'legalBasisReference'),4000); END IF; END IF;\n p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);at:=clock_timestamp();IF p IS NULL OR (p->>'retainUntil')::timestamptz>at THEN RAISE EXCEPTION 'contract_copy_native_deadline_changed';END IF; INSERT INTO gridex_ediel_retention.decision_evidence_tombstones(retention_class,target_id,company_id,policy_id,review_id,source_hash,target_metadata_hash,byte_length,actor_user_id,journal_retain_until,journal_purpose_reference,created_at) VALUES(d.retention_class,d.target_id,p_company_id,d.id,r.id,d.source_hash,d.target_metadata_hash,(basis->>'byteLength')::bigint,p_actor_user_id,(p->>'journalRetainUntil')::timestamptz,p->>'journalPurposeReference',at);\n EXECUTE format('UPDATE gridex_ediel_retention.%I SET document_bytes=NULL,document_byte_length=$1,document_purged_at=$2 WHERE id=$3 AND company_id=$4',spec.source_table) USING (basis->>'byteLength')::bigint,at,d.target_id,p_company_id;\n INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'retention_decision_original',d.target_id,'ediel.retention.decision_original_bytes_removed',jsonb_build_object('policyId',d.id,'reviewId',r.id,'retentionClass',d.retention_class,'sourceHash',d.source_hash,'byteLength',(basis->>'byteLength')::bigint,'journalRetainUntil',p->>'journalRetainUntil','journalPurposeReference',p->>'journalPurposeReference','freshAuthorityRevoked',true));\n RETURN jsonb_build_object('status','purged','retentionClass',d.retention_class,'targetId',d.target_id,'sourceHash',d.source_hash,'byteLength',(basis->>'byteLength')::bigint,'bytesAvailable',false,'authority','none','replay',false);\nEND$_$;","public.ediel_read_retention_decision_original_v1":"CREATE FUNCTION public.ediel_read_retention_decision_original_v1(p_company_id uuid, p_actor_user_id uuid, p_retention_class text, p_target_id uuid, p_include_document boolean DEFAULT false) RETURNS jsonb\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $_$DECLARE tab text;r jsonb;b bytea;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();\n PERFORM gridex_ediel_retention.decision_evidence_lock_v1(p_company_id);\n PERFORM gridex_ediel_retention.decision_evidence_read_actor_v1(p_company_id,p_actor_user_id,p_retention_class);IF p_include_document THEN PERFORM gridex_ediel_retention.decision_evidence_actor_v1(p_company_id,p_actor_user_id,p_retention_class,'ediel.retention.review');END IF;\n IF p_retention_class IN('life_event_classification_source_original_bytes','life_event_classification_receipt_original_bytes','life_event_classification_revocation_original_bytes') THEN r:=gridex_ediel_retention.classification_copy_row_v1(p_company_id,p_retention_class,p_target_id);b:=decode(substr(r->>'document_bytes',3),'hex'); SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=p_retention_class AND target_id=p_target_id AND company_id=p_company_id; RETURN jsonb_build_object('companyId',p_company_id,'retentionClass',p_retention_class,'targetId',p_target_id,'documentHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'documentByteLength',coalesce(octet_length(b),t.byte_length),'bytesAvailable',b IS NOT NULL,'documentBase64',CASE WHEN p_include_document AND b IS NOT NULL THEN replace(encode(b,'base64'),E'\\n','') ELSE NULL END,'purgedAt',t.created_at,'authority','none');END IF; IF p_retention_class IN('masterdata_declaration_agreement_original_bytes','masterdata_declaration_source_original_bytes','masterdata_preparation_agreement_original_bytes','masterdata_preparation_source_original_bytes','metering_contract_request_agreement_original_bytes','metering_contract_request_source_original_bytes','metering_method_event_agreement_original_bytes','metering_method_event_source_original_bytes') THEN r:=gridex_ediel_retention.contract_copy_row_v1(p_company_id,p_retention_class,p_target_id);b:=decode(substr(r->>'document_bytes',3),'hex');SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=p_retention_class AND target_id=p_target_id AND company_id=p_company_id;RETURN jsonb_build_object('companyId',p_company_id,'retentionClass',p_retention_class,'targetId',p_target_id,'documentHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'documentByteLength',coalesce(octet_length(b),t.byte_length),'bytesAvailable',b IS NOT NULL,'documentBase64',CASE WHEN p_include_document AND b IS NOT NULL THEN replace(encode(b,'base64'),E'\\n','') ELSE NULL END,'purgedAt',t.created_at,'authority','none');END IF; IF EXISTS(SELECT FROM gridex_ediel_retention.protected_copy_specs WHERE retention_class=p_retention_class) THEN r:=gridex_ediel_retention.protected_copy_row_v1(p_company_id,p_retention_class,p_target_id);b:=decode(substr(r->>'document_bytes',3),'hex');SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=p_retention_class AND target_id=p_target_id AND company_id=p_company_id;RETURN jsonb_build_object('companyId',p_company_id,'retentionClass',p_retention_class,'targetId',p_target_id,'documentHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'documentByteLength',coalesce(octet_length(b),t.byte_length),'bytesAvailable',b IS NOT NULL,'documentBase64',CASE WHEN p_include_document AND b IS NOT NULL THEN replace(encode(b,'base64'),E'\n','') ELSE NULL END,'purgedAt',t.created_at,'authority','none');END IF; SELECT source_table INTO STRICT tab FROM gridex_ediel_retention.decision_evidence_catalog WHERE retention_class=p_retention_class;EXECUTE format('SELECT to_jsonb(d),d.document_bytes FROM gridex_ediel_retention.%I d WHERE id=$1 AND company_id=$2 FOR SHARE',tab) INTO r,b USING p_target_id,p_company_id;IF r IS NULL THEN RAISE EXCEPTION 'decision_evidence_original_scope_required';END IF;\n SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=p_retention_class AND target_id=p_target_id AND company_id=p_company_id;\n IF b IS NULL AND (t.target_id IS NULL OR r->>'document_hash' IS DISTINCT FROM t.source_hash) OR b IS NOT NULL AND encode(sha256(b),'hex') IS DISTINCT FROM r->>'document_hash' THEN RAISE EXCEPTION 'decision_evidence_original_custody_mismatch';END IF;\n RETURN jsonb_build_object('companyId',p_company_id,'retentionClass',p_retention_class,'targetId',p_target_id,'documentHash',r->>'document_hash','targetMetadataHash',encode(sha256(convert_to((r-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex'),'documentByteLength',coalesce(octet_length(b),t.byte_length),'bytesAvailable',b IS NOT NULL,'documentBase64',CASE WHEN p_include_document AND b IS NOT NULL THEN replace(encode(b,'base64'),E'\\n','') ELSE NULL END,'purgedAt',t.created_at,'authority','none');\nEND$_$;","public.ediel_read_decision_evidence_policy_v1":"CREATE FUNCTION public.ediel_read_decision_evidence_policy_v1(p_company_id uuid, p_actor_user_id uuid, p_policy_id uuid, p_include_document boolean DEFAULT false) RETURNS jsonb\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $$DECLARE d gridex_ediel_retention.decision_evidence_policies%rowtype;p jsonb;r jsonb;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;bytes_length bigint;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();\n PERFORM gridex_ediel_retention.decision_evidence_lock_v1(p_company_id);\n SELECT * INTO STRICT d FROM gridex_ediel_retention.decision_evidence_policies WHERE id=p_policy_id AND company_id=p_company_id FOR SHARE;PERFORM gridex_ediel_retention.decision_evidence_read_actor_v1(p_company_id,p_actor_user_id,d.retention_class);IF p_include_document THEN PERFORM gridex_ediel_retention.decision_evidence_actor_v1(p_company_id,p_actor_user_id,d.retention_class,'ediel.retention.review');END IF;\n IF d.document_bytes IS NOT NULL AND encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RAISE EXCEPTION 'decision_evidence_policy_original_hash_required';END IF;\n p:=gridex_ediel_retention.decision_evidence_receipt_v1(d);SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=d.retention_class AND target_id=d.target_id AND company_id=p_company_id;\n SELECT coalesce(jsonb_agg(jsonb_build_object('reviewId',id,'actorUserId',actor_user_id,'outcome',outcome,'reason',reason,'createdAt',created_at) ORDER BY created_at,id),'[]') INTO r FROM gridex_ediel_retention.decision_evidence_reviews WHERE policy_id=d.id;\n bytes_length:=coalesce(octet_length(d.document_bytes),d.document_byte_length);\n RETURN jsonb_build_object('companyId',d.company_id,'policyId',d.id,'retentionClass',d.retention_class,'targetId',d.target_id,'sourceHash',d.source_hash,'targetMetadataHash',d.target_metadata_hash,'documentHash',d.document_hash,'documentByteLength',bytes_length,'bytesAvailable',d.document_bytes IS NOT NULL,'documentPurgedAt',d.document_purged_at,'documentBase64',CASE WHEN p_include_document AND d.document_bytes IS NOT NULL THEN replace(encode(d.document_bytes,'base64'),E'\\n','') ELSE NULL END,'submittedBy',d.submitted_by,'createdAt',d.created_at,'issuerQualified',p IS NOT NULL,'currentQualified',gridex_ediel_retention.decision_evidence_policy_current_v1(d),'revoked',EXISTS(SELECT FROM gridex_ediel_retention.decision_evidence_revocations WHERE policy_id=d.id),'reviews',r,'purge',CASE WHEN t.target_id IS NULL THEN NULL ELSE jsonb_build_object('purgedAt',t.created_at,'sourceHash',t.source_hash,'byteLength',t.byte_length) END,'authority','none');\nEND$$;","gridex_ediel_retention.decision_evidence_lock_v1":"CREATE FUNCTION gridex_ediel_retention.decision_evidence_lock_v1(c uuid) RETURNS void\n    LANGUAGE sql\n    SET search_path TO 'pg_catalog'\n    AS $$SELECT pg_advisory_xact_lock(hashtextextended('gridex:retention:decision-original:'||c::text,0))$$;","gridex_ediel_retention.decision_evidence_policies_original_guard_v1":"CREATE FUNCTION gridex_ediel_retention.decision_evidence_policies_original_guard_v1() RETURNS trigger\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $$\nBEGIN IF TG_OP='UPDATE' AND gridex_ediel_retention.decision_evidence_transition_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) IS TRUE THEN RETURN NEW;END IF;\n  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';\nEND\n$$;","gridex_ediel_retention.decision_evidence_transition_v1":"CREATE FUNCTION gridex_ediel_retention.decision_evidence_transition_v1(tab text, o jsonb, n jsonb) RETURNS boolean\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    AS $$DECLARE k text;t gridex_ediel_retention.decision_evidence_tombstones%rowtype;BEGIN\n SELECT retention_class INTO k FROM gridex_ediel_retention.decision_evidence_catalog WHERE source_table=tab;SELECT * INTO t FROM gridex_ediel_retention.decision_evidence_tombstones WHERE retention_class=k AND target_id=(o->>'id')::uuid AND company_id=(o->>'company_id')::uuid;\n RETURN t.target_id IS NOT NULL AND o->>'document_bytes' IS NOT NULL AND n->>'document_bytes' IS NULL AND (n->>'document_purged_at')::timestamptz=t.created_at AND (n->>'document_byte_length')::bigint=t.byte_length AND o->>'document_hash'=t.source_hash AND encode(sha256(convert_to((o-ARRAY['document_bytes','document_byte_length','document_purged_at'])::text,'UTF8')),'hex')=t.target_metadata_hash AND (o-ARRAY['document_bytes','document_byte_length','document_purged_at'])=(n-ARRAY['document_bytes','document_byte_length','document_purged_at']);\nEND$$;","gridex_received_sources.reject_mutation":"CREATE FUNCTION gridex_received_sources.reject_mutation() RETURNS trigger\n    LANGUAGE plpgsql\n    SET search_path TO 'pg_catalog'\n    AS $$\nBEGIN\n  RAISE EXCEPTION 'received_source_evidence_is_append_only' USING ERRCODE = '23514';\nEND\n$$;","gridex_received_sources.other_supply_scope_effect_v1":"CREATE FUNCTION gridex_received_sources.other_supply_scope_effect_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_scope jsonb, p_source_cohort uuid[], p_canonical_id uuid) RETURNS jsonb\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO 'pg_catalog'\n    SET \"TimeZone\" TO 'UTC'\n    AS $$\nDECLARE m public.ediel_messages%rowtype;sp public.customer_supply_periods%rowtype;sw public.supplier_switch_requests%rowtype;origin public.ediel_messages%rowtype;\n prior gridex_received_sources.supply_source_transitions%rowtype;ground gridex_received_sources.regulated_supply_ground_versions%rowtype;\n wire jsonb;sender_basis jsonb;original jsonb;own jsonb;entry jsonb;plan jsonb;plans jsonb:='[]';before_states jsonb:='[]';previous_switches jsonb:='[]';after_states jsonb;old jsonb;\n ids uuid[];point public.metering_points%rowtype;consumption public.metering_points%rowtype;legal_actor uuid;dso_actor uuid;\n event_at timestamptz;start_at timestamptz;reason text;period_id uuid;expected_version bigint;qualified boolean;\nBEGIN\n SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE; IF gridex_received_sources.require_supply_scope_admission_v1(p_company_id,p_source_message_id,p_scope) IS DISTINCT FROM p_canonical_id THEN RAISE EXCEPTION 'supply_scoped_canonical_assessment_changed';END IF; IF jsonb_array_length(gridex_received_sources.require_prodat_application_objects_v1(p_company_id,p_source_message_id)->'objects')>1 THEN m.customer_id:=NULL;m.metering_point_id:=NULL;END IF;\n IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_source_unavailable');END IF;\n PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;\n PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;\n IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)\n OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) THEN RETURN jsonb_build_object('applied',false,'reason','supply_execution_actor_unqualified');END IF;\n SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;\n IF FOUND AND (prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'supply_replay_conflict';END IF;\n IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.id=p_canonical_id AND v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')\n AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_supply_source_not_accepted');END IF;\n wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);\n IF wire IS NULL OR (wire->>'code' IN ('Z04','Z05')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_wire_unavailable');END IF;\n -- No mixed physical subtype, duplicate point, or partially applied message.\n SELECT o->>'reason' INTO reason FROM jsonb_array_elements(wire->'objects') o LIMIT 1;\n IF nullif(reason,'') IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason' IS DISTINCT FROM reason OR nullif(o->>'point','') IS NULL OR nullif(o->>'li','') IS NULL)\n OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','supply_object_scope_unqualified');END IF;\n IF prior.source_message_id IS NOT NULL THEN\n  IF wire->>'code'='Z04' AND reason IN('Z26','Z70') AND EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE gridex_regulated_supply.ground_current_v1((saved#>>'{metadata,sourceGroundId}')::uuid,m.company_id,(saved->>'metering_point_id')::uuid,(saved->>'market_start_at')::timestamptz) IS NOT TRUE) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_current_ground_required');END IF;\n  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states);\n END IF;\n -- Only a first Z05/C restoration requires today's actual sender registry.\n -- Historical recorded outcomes returned above retain their original truth.\n IF wire->>'code'='Z05' AND reason='Z24' THEN\n  sender_basis:=gridex_network_registry_sources.network_for_company_v1(m.company_id,wire->>'sender',m.environment);\n  IF sender_basis->>'status' IS DISTINCT FROM 'authorized'\n   OR sender_basis#>>'{basis,companyId}' IS DISTINCT FROM m.company_id::text\n   OR sender_basis#>>'{basis,environment}' IS DISTINCT FROM m.environment\n   OR sender_basis#>>'{basis,networkEdielId}' IS DISTINCT FROM wire->>'sender'\n   THEN RETURN jsonb_build_object('applied',false,'reason','z05c_current_sender_network_registry_required');END IF;\n END IF;\n -- Only a first Z04/C cancellation requires today's actual sender registry.\n -- Historical recorded outcomes returned above retain their original truth.\n IF wire->>'code'='Z04' AND reason='Z24' THEN\n  sender_basis:=gridex_network_registry_sources.network_for_company_v1(m.company_id,wire->>'sender',m.environment);\n  IF sender_basis->>'status' IS DISTINCT FROM 'authorized'\n   OR sender_basis#>>'{basis,companyId}' IS DISTINCT FROM m.company_id::text\n   OR sender_basis#>>'{basis,environment}' IS DISTINCT FROM m.environment\n   OR sender_basis#>>'{basis,networkEdielId}' IS DISTINCT FROM wire->>'sender'\n   THEN RETURN jsonb_build_object('applied',false,'reason','z04c_current_sender_network_registry_required');END IF;\n END IF;\n PERFORM tp.id FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment ORDER BY tp.id FOR SHARE;\n PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment=m.environment ORDER BY i.id FOR SHARE;\n PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=m.company_id AND r.environment=m.environment ORDER BY r.id FOR SHARE;\n IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment AND tp.market='electricity' AND tp.is_enabled AND tp.valid_from<=m.message_received_at AND (tp.valid_to IS NULL OR m.message_received_at<tp.valid_to)) THEN RETURN jsonb_build_object('applied',false,'reason','supply_tenant_profile_unqualified');END IF;\n SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id\n WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=wire->>'receiver' AND i.valid_from<=m.message_received_at AND (i.valid_to IS NULL OR m.message_received_at<i.valid_to)\n AND r.role_code='electricity_supplier' AND r.valid_from<=m.message_received_at AND (r.valid_to IS NULL OR m.message_received_at<r.valid_to);\n IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','supply_legal_actor_unqualified');END IF;legal_actor:=ids[1];\n FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP\n  event_at:=gridex_received_sources.permission_time_v1(own->>CASE WHEN wire->>'code'='Z04' THEN 'start' ELSE 'end' END);\n  IF event_at IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_effective_time_unavailable');END IF;\n  IF wire->>'code'='Z04' AND reason IN ('Z26','Z70') THEN\n   SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_area_code=own->>'gridArea' AND mp.grid_owner_ediel_id=wire->>'sender'\n    AND mp.customer_id IS NOT NULL AND (m.customer_id IS NULL OR m.customer_id=mp.customer_id) AND (m.metering_point_id IS NULL OR m.metering_point_id=mp.id);\n   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_exact_object_unavailable');END IF;\n   SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;\n   PERFORM customer.id FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id FOR SHARE;\n   IF NOT EXISTS(SELECT FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id AND own->>'customerIdentity'=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_customer_identity_unqualified');END IF;\n   PERFORM ai.id FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' ORDER BY ai.id FOR SHARE;\n   SELECT array_agg(DISTINCT ai.actor_id) INTO ids FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' AND ai.is_verified AND (ai.valid_from IS NULL OR ai.valid_from<=(m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date) AND (ai.valid_to IS NULL OR (m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date<=ai.valid_to);\n   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_dso_registry_unavailable');END IF;dso_actor:=ids[1];\n   PERFORM ba.id FROM public.tenant_bilateral_agreements ba WHERE ba.company_id=m.company_id AND ba.environment=m.environment AND ba.counterparty_actor_id=dso_actor ORDER BY ba.id FOR SHARE;\n   PERFORM g.id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' ORDER BY g.id FOR SHARE;\n   SELECT array_agg(g.id ORDER BY g.id) INTO ids FROM gridex_received_sources.regulated_supply_ground_versions g JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id\n   WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' AND g.process=CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END\n    AND gridex_regulated_supply.ground_wire_current_v1(g.id,m.company_id,point.id,event_at,own) IS TRUE\n    AND g.approved_at<=m.message_received_at AND g.revoked_at IS NULL AND g.valid_from<=event_at AND (g.valid_to IS NULL OR event_at<g.valid_to) AND ba.is_enabled AND ba.valid_from<=event_at AND (ba.valid_to IS NULL OR event_at<ba.valid_to) AND ba.source_reference=g.source_reference;\n   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_authentic_ground_required');END IF;\n   SELECT * INTO ground FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ids[1] FOR SHARE;\n   IF reason='Z70' THEN\n    SELECT cp.* INTO consumption FROM public.customer_supply_periods rel JOIN public.metering_points cp ON cp.id=rel.metering_point_id AND cp.company_id=rel.company_id JOIN public.customer_contracts cc ON cc.id=coalesce(rel.customer_contract_id,rel.contract_id) AND cc.company_id=rel.company_id AND cc.customer_id=rel.customer_id\n    WHERE rel.id=ground.consumption_supply_period_id AND rel.company_id=m.company_id AND rel.customer_id=point.customer_id AND cp.ediel_metering_point_id=own->>'consumptionPoint' AND cp.product_direction='consumption' AND cc.energy_direction='consumption' AND cc.status IN ('signed','active') AND rel.status IN ('active','confirmed_by_grid_owner')\n    AND rel.start_date<=gridex_received_sources.permission_date_v1(own->>'start') AND (rel.end_date IS NULL OR rel.end_date>gridex_received_sources.permission_date_v1(own->>'start')) FOR SHARE OF rel,cp,cc;\n    IF NOT FOUND OR point.product_direction IS DISTINCT FROM 'production' THEN RETURN jsonb_build_object('applied',false,'reason','production_obligation_own_consumption_link_required');END IF;\n   END IF;\n   IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN ('cancelled','ended') AND (p.end_date IS NULL OR p.end_date>gridex_received_sources.permission_date_v1(own->>'start'))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_conflicting_period');END IF;\n   period_id:=gen_random_uuid();plans:=plans||jsonb_build_array(jsonb_build_object('kind','regulated','periodId',period_id,'pointId',point.id,'customerId',point.customer_id,'eventAt',event_at,'groundId',ground.id,'object',own));\n  ELSIF wire->>'code'='Z04' AND reason='Z24' THEN\n   -- Match every cancellation to its sealed, actually sent original Z03.\n   SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment\n    WHERE s.company_id=m.company_id AND z.direction='outbound' AND gridex_received_sources.sent_source_is_current_v1(z)\n    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->'objects') o WHERE o->>'point'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))\n    AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender';\n   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_exact_original_unavailable');END IF;\n   SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;\n   IF coalesce(sw.outbound_z03_message_id=ANY(p_source_cohort),false) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_original_cohort_changed');END IF;SELECT * INTO origin FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;\n   original:=coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(m.company_id,origin.id,sp.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload));\n   IF NOT FOUND OR origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE\n    OR original IS NULL OR original->>'code' IS DISTINCT FROM 'Z03' OR original->>'sender' IS DISTINCT FROM wire->>'receiver' OR original->>'receiver' IS DISTINCT FROM wire->>'sender'\n    OR origin.customer_id IS DISTINCT FROM sw.customer_id OR origin.metering_point_id IS DISTINCT FROM sw.metering_point_id OR (m.customer_id IS NOT NULL AND m.customer_id<>sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sw.metering_point_id)\n    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))\n    THEN RETURN jsonb_build_object('applied',false,'reason','z04c_locked_original_mismatch');END IF;\n   -- A start already cancelled by another own C is a held duplicate.\n   IF sw.status='cancelled_before_start' THEN RETURN jsonb_build_object('applied',false,'reason','z04c_start_already_cancelled');END IF;\n   -- An executed own start is corrected under review; it is never reversed here.\n   IF sw.status='completed' THEN\n    IF EXISTS(SELECT FROM gridex_received_sources.supply_object_effect_receipts e WHERE e.company_id=m.company_id AND e.environment=m.environment\n     AND e.effect_text::jsonb#>>'{plan,kind}'='executed_start_compensation' AND e.effect_text::jsonb#>>'{plan,executedSwitchId}'=sw.id::text) THEN RETURN jsonb_build_object('applied',false,'reason','z04c_executed_start_compensation_already_recorded');END IF;\n    SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p\n     JOIN gridex_received_sources.normal_switch_confirmations c ON c.period_id=p.id AND c.company_id=p.company_id\n     JOIN gridex_received_sources.normal_supply_activations a ON a.period_id=p.id AND a.company_id=p.company_id AND a.source_message_id=c.source_message_id\n     WHERE p.company_id=m.company_id AND p.customer_id=sw.customer_id AND p.metering_point_id=sw.metering_point_id AND (p.status IN ('active','ending','ended')) IS TRUE\n      AND c.switch_id=sw.id AND c.original_message_id=origin.id AND c.original_payload_hash=origin.immutable_payload_hash AND c.source_message_id=sw.inbound_z04_message_id\n      AND p.start_date=gridex_received_sources.permission_date_v1(own->>'start') AND c.market_start_at<=now();\n    IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;\n    SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR SHARE;\n    previous_switches:=previous_switches||jsonb_build_array(to_jsonb(sw));\n    plans:=plans||jsonb_build_array(jsonb_build_object('kind','executed_start_compensation','switchId',NULL,'periodId',NULL,'disposition','controlled_review',\n     'executedSwitchId',sw.id,'executedPeriodId',sp.id,'executedPeriod',to_jsonb(sp),'originalId',origin.id,'originalHash',origin.immutable_payload_hash,\n     'confirmationSourceMessageId',sw.inbound_z04_message_id,'siteId',coalesce(sw.site_id,sw.customer_site_id),'caseId',gen_random_uuid(),'object',own));\n    CONTINUE;\n   END IF;\n   IF (sw.status IN ('draft','prepared','queued','sent','submitted','waiting','waiting_for_z04','accepted','cancellation_requested','cancelled_before_start')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;\n   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.customer_id=sw.customer_id AND p.metering_point_id=sw.metering_point_id AND (p.source_switch_request_id=sw.id OR p.source_message_id=sw.inbound_z04_message_id);\n   IF coalesce(cardinality(ids),0)>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_conflicting_periods');END IF;\n   IF coalesce(cardinality(ids),0)=1 THEN\n    SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;\n    IF sp.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR sp.customer_id IS DISTINCT FROM sw.customer_id OR sp.metering_point_id IS DISTINCT FROM sw.metering_point_id OR sp.start_date IS DISTINCT FROM gridex_received_sources.permission_date_v1(own->>'start') OR coalesce(sp.market_start_at,sp.start_date::timestamp AT TIME ZONE 'Etc/GMT-1')<=now() THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;\n    before_states:=before_states||jsonb_build_array(to_jsonb(sp));period_id:=sp.id;\n   ELSE period_id:=NULL;END IF;\n   previous_switches:=previous_switches||jsonb_build_array(to_jsonb(sw));plans:=plans||jsonb_build_array(jsonb_build_object('kind','cancel_start','periodId',period_id,'switchId',sw.id,'object',own));\n  ELSIF wire->>'code'='Z05' AND reason='Z24' THEN\n   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id\n    JOIN public.ediel_messages z ON z.id=tr.source_message_id AND z.company_id=tr.company_id AND z.environment=m.environment\n    WHERE p.company_id=m.company_id AND z.direction='inbound' AND tr.payload_hash=encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex') AND coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p.company_id,z.id,p.id),gridex_received_sources.normal_switch_wire_v1(z.raw_payload))->>'sender'=wire->>'sender' AND coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p.company_id,z.id,p.id),gridex_received_sources.normal_switch_wire_v1(z.raw_payload))->>'receiver'=wire->>'receiver' AND EXISTS(SELECT FROM jsonb_array_elements(coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p.company_id,z.id,p.id),gridex_received_sources.normal_switch_wire_v1(z.raw_payload))->'objects') original_scope WHERE original_scope->>'point'=own->>'point' AND original_scope->>'identityAgency'=own->>'identityAgency')\n    AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'end'=own->>'end')\n    AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND (state->>'market_state_version')::bigint=p.market_state_version AND (state-ARRAY['updated_at','status'])=(to_jsonb(p)-ARRAY['updated_at','status']));\n   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05c_exact_original_ending_unavailable');END IF;\n   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;\n   IF coalesce(sp.source_end_message_id=ANY(p_source_cohort),false) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_original_cohort_changed');END IF;SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=sp.source_end_message_id AND company_id=m.company_id;\n   SELECT state INTO old FROM jsonb_array_elements(prior.previous_states) state WHERE state->>'id'=sp.id::text;\n   IF old IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE saved->>'id'=sp.id::text AND (sp.status=saved->>'status' OR sp.status='ended' AND saved->>'status'='ending' AND sp.market_end_at<=now())) OR EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=sp.metering_point_id AND p.id<>sp.id AND p.status NOT IN ('ended','cancelled') AND (p.end_date IS NULL OR p.end_date>sp.start_date)) THEN RETURN jsonb_build_object('applied',false,'reason','z05c_conflicting_continuation');END IF;\n   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','restore_end','periodId',sp.id,'previous',old,'object',own));\n  ELSIF wire->>'code'='Z05' AND reason IN ('Z22','Z23') THEN\n   -- Actual accepted baseline owner ties the physical object to a relationship;\n   -- a unique local row or DATE similarity is never sufficient authority.\n   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p\n    WHERE p.company_id=m.company_id AND p.status IN ('active','confirmed_by_grid_owner','ending') AND p.source_end_message_id IS NULL AND (\n     EXISTS(SELECT FROM gridex_received_sources.object_assessments assessment JOIN gridex_received_sources.sources src ON src.source_message_id=assessment.source_message_id AND src.company_id=assessment.company_id AND src.payload_hash=assessment.source_payload_hash\n      JOIN public.ediel_messages base ON base.id=src.source_message_id AND base.company_id=src.company_id AND base.environment=src.environment AND base.direction='inbound' AND src.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')\n      CROSS JOIN LATERAL jsonb_array_elements(assessment.facts_text::jsonb->'objects') object\n      WHERE assessment.company_id=p.company_id AND assessment.environment=m.environment AND assessment.source_message_id=p.source_message_id\n       AND object->>'disposition'='accepted' AND object#>>'{object,objectId}'=own->>'point' AND object#>>'{object,identityAgency}'='9'\n       AND object#>>'{business,supplyPeriodId}'=p.id::text AND object#>>'{business,customerId}'=p.customer_id::text AND object#>>'{business,meteringPointId}'=p.metering_point_id::text\n       AND object#>>'{business,owner}' IN ('inbound-z04-switch-confirmation-v1','reviewed-received-structure-v1')\n       AND object#>>'{party,parties,legalSender}'=wire->>'sender' AND object#>>'{party,parties,legalReceiver}'=wire->>'receiver'\n       AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=assessment.id))\n     OR EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr JOIN public.ediel_messages base ON base.id=tr.source_message_id AND base.company_id=tr.company_id AND base.environment=m.environment AND base.direction='inbound'\n      WHERE tr.company_id=p.company_id AND tr.source_message_id=p.source_message_id AND tr.source_code='Z04' AND tr.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')\n       AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND state->>'customer_id'=p.customer_id::text AND state->>'metering_point_id'=p.metering_point_id::text AND(state#>>'{metadata,sourceObject,point}'=own->>'point' OR state#>>'{metadata,normalSourceBasis,object,point}'=own->>'point'))\n       AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) object WHERE object->>'point'=own->>'point' AND object->>'customerIdentity'=own->>'customerIdentity' AND object->>'gridArea'=own->>'gridArea' AND (object->>'reason' IN ('Z26','Z70') OR object->>'reason' IN ('Z22','Z23') AND EXISTS(SELECT FROM gridex_received_sources.supply_object_effect_receipts own_effect WHERE own_effect.company_id=p.company_id AND own_effect.source_message_id=tr.source_message_id AND own_effect.object_scope->>'objectId'=own->>'point' AND own_effect.object_scope->>'identityAgency'=own->>'identityAgency' AND gridex_received_sources.supply_effect_assessment_owns_period_v1(p.company_id,tr.source_message_id,p.id,own_effect.canonical_assessment_id)))))\n    );\n   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05_accepted_relationship_baseline_required');END IF;\n   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;\n   IF coalesce(sp.source_message_id=ANY(p_source_cohort),false) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_original_cohort_changed');END IF;SELECT * INTO origin FROM public.ediel_messages WHERE id=sp.source_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;\n   original:=coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(m.company_id,origin.id,sp.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload));\n   IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z04' OR original->>'sender' IS DISTINCT FROM wire->>'sender' OR original->>'receiver' IS DISTINCT FROM wire->>'receiver'\n    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'gridArea'=own->>'gridArea' AND gridex_received_sources.permission_time_v1(o->>'start')<event_at)\n    OR (m.customer_id IS NOT NULL AND m.customer_id<>sp.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sp.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','z05_original_object_mismatch');END IF;\n   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','end','periodId',sp.id,'eventAt',event_at,'object',own));\n  ELSE RETURN jsonb_build_object('applied',false,'reason','supply_profile_not_qualified');END IF;\n END LOOP;\n -- All owned objects, current originals and ground records are locked/qualified.\n FOR plan IN SELECT x FROM jsonb_array_elements(plans) x LOOP\n  IF plan->>'kind'='regulated' THEN\n   INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,start_date,market_start_at,source,source_process,source_message_id,status,market_state_version,metadata)\n    VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source',CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END,m.id,'confirmed_by_grid_owner',1,jsonb_build_object('sourceGroundId',plan->>'groundId','sourceObject',plan->'object','sourceReceivedAt',m.message_received_at));\n  ELSIF plan->>'kind'='cancel_start' THEN\n   UPDATE public.supplier_switch_requests SET status='cancelled_before_start',inbound_z04_message_id=m.id,completed_at=now(),updated_at=now() WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;\n   UPDATE public.customer_supply_periods SET status='cancelled',market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('startCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;\n  ELSIF plan->>'kind'='executed_start_compensation' THEN\n   INSERT INTO public.customer_cases(id,company_id,customer_id,site_id,metering_point_id,customer_contract_id,supplier_switch_request_id,case_type,status,priority,title,description,reason_category,next_action,source,metadata,created_by,updated_by,source_ediel_message_id,source_business_process)\n    VALUES((plan->>'caseId')::uuid,m.company_id,(plan#>>'{executedPeriod,customer_id}')::uuid,(plan->>'siteId')::uuid,(plan#>>'{executedPeriod,metering_point_id}')::uuid,\n     coalesce(plan#>>'{executedPeriod,customer_contract_id}',plan#>>'{executedPeriod,contract_id}')::uuid,(plan->>'executedSwitchId')::uuid,'other','manual_follow_up','high',\n     'Annullering efter genomförd leveransstart – korrigera',\n     'Nätägaren har annullerat en leveransstart som redan genomförts. Annulleringen är besvarad. Korrigera starten med bibehållen historik och kompensera vid behov.',\n     'executed_start_cancellation','Utred och genomför korrigering av den genomförda starten.','ediel_inbound_state_machine',\n     jsonb_build_object('review_intent','executed_start_compensation','source_ediel_message_id',m.id,'executed_switch_id',plan->'executedSwitchId','executed_period_id',plan->'executedPeriodId',\n      'original_message_id',plan->'originalId','original_payload_hash',plan->'originalHash','confirmation_source_message_id',plan->'confirmationSourceMessageId','object',plan->'object'),\n     p_actor_user_id,p_actor_user_id,m.id,'supplier_switch');\n  ELSIF plan->>'kind'='end' THEN\n   UPDATE public.customer_supply_periods SET end_date=gridex_received_sources.permission_date_v1(plan#>>'{object,end}'),market_end_at=(plan->>'eventAt')::timestamptz,source_end_message_id=m.id,status=CASE WHEN (plan->>'eventAt')::timestamptz<=now() THEN 'ended' ELSE 'ending' END,market_state_version=market_state_version+1,updated_at=now() WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;\n  ELSIF plan->>'kind'='restore_end' THEN\n   UPDATE public.customer_supply_periods SET status=plan#>>'{previous,status}',end_date=(plan#>>'{previous,end_date}')::date,market_end_at=(plan#>>'{previous,market_end_at}')::timestamptz,source_end_message_id=(plan#>>'{previous,source_end_message_id}')::uuid,market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('endCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;\n  END IF;\n END LOOP;\n SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN (SELECT (chosen_plan->>'periodId')::uuid FROM jsonb_array_elements(plans) chosen_plan);\n\n RETURN jsonb_build_object('applied',true,'periods',after_states,'plans',plans,'previousStates',before_states,'previousSwitches',previous_switches,'regulated',wire->>'code'='Z04' AND reason IN ('Z26','Z70'));\nEND $$;","gridex_prodat_object_batch.require_wire_projection_v1":"CREATE FUNCTION gridex_prodat_object_batch.require_wire_projection_v1(raw text, own jsonb, command jsonb, mode text, actor uuid) RETURNS void\n    LANGUAGE plpgsql\n    SET search_path TO 'pg_catalog'\n    AS $_$\nDECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);raw_parts jsonb:=gridex_prodat_object_batch.raw_segments_v1(raw);t jsonb;e jsonb;first_index int:=(own#>>'{registers,0,segmentIndex}')::int;next_index int;\n ud jsonb;it jsonb;qty text;start_day text;frequency text;product text;reference text;area text;grid_id uuid;characteristic text;name text;personal text;org text;is_business bool;key text;expected jsonb;field_value jsonb;reg jsonb;wire_reg jsonb;reg_end int;reg_raw jsonb;reg_qty text;\n source_company uuid;source_id uuid;source_hash text;source_row public.ediel_messages%rowtype;source_original gridex_received_sources.sources%rowtype;\n application jsonb;ignored gridex_received_sources.prodat_ignored_field_facets%rowtype;fields jsonb;field jsonb;occ jsonb;physical jsonb;owner_object jsonb;owner_register jsonb;\n first_owner_index int;first_owner_end int;first_party_index int;li text;customer_ref text;li_count int;customer_count int;refs jsonb;own_fields text[]:=ARRAY[]::text[];\nBEGIN\n IF tokens IS NULL THEN RAISE EXCEPTION 'prodat_object_batch_physical_projection_required';END IF;\n SELECT min((x->>'index')::int) INTO next_index FROM jsonb_array_elements(tokens)x WHERE x->>'tag' IN('LIN','UNT') AND (x->>'index')::int>first_index;\n FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>first_index AND (x->>'index')::int<next_index ORDER BY(x->>'index')::int LOOP\n  e:=t->'elements';\n  IF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN ud:=e;ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='IT' THEN it:=e;\n  ELSIF t->>'tag'='QTY' AND e#>>'{1,0}'='31' THEN qty:=e#>>'{1,1}';\n  ELSIF t->>'tag'='DTM' AND e#>>'{1,0}'='92' THEN start_day:=e#>>'{1,1}';\n  ELSIF t->>'tag'='RFF' AND e#>>'{1,0}'='Z07' THEN reference:=e#>>'{1,1}';\n  ELSIF t->>'tag'='RFF' AND e#>>'{1,0}'='Z05' THEN area:=e#>>'{1,1}';\n  ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';\n  ELSIF t->>'tag'='CAV' AND characteristic='Z12' THEN frequency:=e#>>'{1,3}';\n  ELSIF t->>'tag'='CAV' AND characteristic='Z14' THEN product:=e#>>'{1,3}';END IF;\n END LOOP;\n FOR reg IN SELECT value FROM jsonb_array_elements(command#>'{application,payload_snapshot,prodatRegisters}') LOOP\n  SELECT x INTO wire_reg FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND x#>>'{elements,1,0}'=reg->>'lineSequenceNumber';\n  SELECT min((x->>'index')::int) INTO reg_end FROM jsonb_array_elements(tokens)x WHERE x->>'tag' IN('LIN','UNT') AND (x->>'index')::int>(wire_reg->>'index')::int;\n  SELECT jsonb_agg(raw_parts->((x->>'index')::int) ORDER BY(x->>'index')::int) INTO reg_raw FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>=(wire_reg->>'index')::int AND(x->>'index')::int<reg_end;\n  SELECT btrim(x#>>'{elements,1,1}') INTO reg_qty FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='QTY' AND x#>>'{elements,1,0}'='31' AND(x->>'index')::int>(wire_reg->>'index')::int AND(x->>'index')::int<reg_end;\n  IF wire_reg IS NULL OR wire_reg#>>'{elements,3,0}' IS DISTINCT FROM own->>'objectId' OR wire_reg#>>'{elements,3,3}' IS DISTINCT FROM own->>'identityAgency'\n   OR reg->>'meteringPointId' IS DISTINCT FROM own->>'objectId' OR reg->>'identityAgency' IS DISTINCT FROM own->>'identityAgency'\n   OR reg->'rawSegments' IS DISTINCT FROM reg_raw OR reg->>'annualConsumption' IS DISTINCT FROM reg_qty OR reg->>'registerIndex' IS DISTINCT FROM nullif(wire_reg#>>'{elements,4,1}','')\n   OR NOT EXISTS(SELECT FROM jsonb_array_elements(own->'registers')r WHERE r->'lineIndex'=reg->'sourceOrder' AND r->>'lineNumber'=reg->>'lineSequenceNumber' AND r->'segmentIndex'=wire_reg->'index') THEN RAISE EXCEPTION 'prodat_object_batch_physical_register_required';END IF;\n END LOOP;\n IF mode='link_existing_only' THEN\n  IF command->'customer'<>'{}'::jsonb OR command->'site' IS DISTINCT FROM jsonb_build_object('facility_id',own->>'objectId') OR command->'metering_point' IS DISTINCT FROM jsonb_build_object('meter_point_id',own->>'objectId') OR command->'update_existing' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'prodat_object_batch_link_identity_only_required';END IF;RETURN;\n END IF;\n -- Same immutable canonical assessment under the caller's existing graph\n -- lock; raw/register snapshots stay intact. Missing facets are UNKNOWN/HOLD.\n source_company:=(command->>'company_id')::uuid;\n source_id:=(command#>>'{application,payload_snapshot,edielMessageId}')::uuid;\n source_hash:=encode(sha256(convert_to(raw,'UTF8')),'hex');\n SELECT * INTO source_row FROM public.ediel_messages WHERE id=source_id AND company_id=source_company;\n SELECT * INTO source_original FROM gridex_received_sources.sources WHERE source_message_id=source_id AND company_id=source_company AND environment=source_row.environment;\n IF source_row.id IS NULL OR source_original.source_message_id IS NULL OR source_row.direction IS DISTINCT FROM 'inbound'\n  OR source_row.message_family IS DISTINCT FROM 'PRODAT' OR source_row.message_standard IS DISTINCT FROM 'edifact'\n  OR source_row.raw_payload IS DISTINCT FROM raw OR source_original.raw_payload IS DISTINCT FROM raw\n  OR source_original.payload_hash IS DISTINCT FROM source_hash OR source_original.message_code IS DISTINCT FROM source_row.message_code\n  OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH' AND x#>>'{elements,2,0}'='PRODAT')<>1\n  THEN RAISE EXCEPTION 'prodat_object_batch_ignored_same_source_required';END IF;\n application:=gridex_received_sources.require_prodat_application_objects_v1(source_company,source_id);\n IF application->>'sourcePayloadHash' IS DISTINCT FROM source_hash\n  OR (SELECT count(*) FROM jsonb_array_elements(application->'objects')x WHERE x=own)<>1\n  THEN RAISE EXCEPTION 'prodat_object_batch_ignored_same_application_required';END IF;\n SELECT * INTO ignored FROM gridex_received_sources.prodat_ignored_field_facets WHERE canonical_assessment_id=(application->>'assessmentId')::uuid\n  AND company_id=source_company AND environment=source_row.environment AND source_message_id=source_id AND source_payload_hash=source_hash;\n IF ignored.canonical_assessment_id IS NULL OR ignored.fields_hash IS DISTINCT FROM encode(sha256(convert_to(ignored.fields_text,'UTF8')),'hex')\n  OR octet_length(ignored.fields_text)>262144 THEN RAISE EXCEPTION 'prodat_object_batch_ignored_canonical_facet_required';END IF;\n fields:=ignored.fields_text::jsonb;\n IF jsonb_typeof(fields) IS DISTINCT FROM 'array' OR jsonb_array_length(fields)>8192\n  OR (SELECT count(*) FROM jsonb_array_elements(fields)x)<>(SELECT count(DISTINCT x) FROM jsonb_array_elements(fields)x)\n  THEN RAISE EXCEPTION 'prodat_object_batch_ignored_field_scope_invalid';END IF;\n FOR field IN SELECT value FROM jsonb_array_elements(fields) LOOP\n  occ:=field->'occurrence';\n  IF jsonb_typeof(field) IS DISTINCT FROM 'object' OR field-ARRAY['fieldNumber','sourceRule','occurrence']<>'{}'::jsonb\n   OR jsonb_typeof(field->'fieldNumber') IS DISTINCT FROM 'string' OR nullif(btrim(field->>'fieldNumber'),'') IS NULL\n   OR field->>'sourceRule' IS DISTINCT FROM 'PRODAT26A:P119' OR jsonb_typeof(occ) IS DISTINCT FROM 'object'\n   OR NOT(occ ?& ARRAY['scope','messageReference','lineIndex','lineNumber','registerPosition','objectId','identityAgency','lineItemReference','ownReferences'])\n   OR occ-ARRAY['scope','messageReference','lineIndex','lineNumber','registerPosition','objectId','identityAgency','lineItemReference','ownReferences']<>'{}'::jsonb\n   OR (occ->>'scope' IN('header','object','register')) IS NOT TRUE\n   OR occ->>'messageReference' IS DISTINCT FROM own->>'messageReference'\n   OR occ->>'messageReference' IS DISTINCT FROM (SELECT x#>>'{elements,1,0}' FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH')\n   THEN RAISE EXCEPTION 'prodat_object_batch_ignored_field_scope_invalid';END IF;\n  IF occ->>'scope'='header' THEN\n   IF occ->'lineIndex' IS DISTINCT FROM 'null'::jsonb OR occ->'lineNumber' IS DISTINCT FROM 'null'::jsonb\n    OR occ->'registerPosition' IS DISTINCT FROM 'null'::jsonb OR occ->'objectId' IS DISTINCT FROM 'null'::jsonb\n    OR occ->'identityAgency' IS DISTINCT FROM 'null'::jsonb OR occ->'lineItemReference' IS DISTINCT FROM 'null'::jsonb\n    OR occ ? 'ownReferences' AND occ->'ownReferences' IS DISTINCT FROM jsonb_build_object('objectId',jsonb_build_object('kind','unavailable'),'lineItemReference',jsonb_build_object('kind','unavailable'),'customerId',jsonb_build_object('kind','unavailable'))\n    THEN RAISE EXCEPTION 'prodat_object_batch_ignored_field_physical_scope_invalid';END IF;\n   CONTINUE;\n  END IF;\n  IF jsonb_typeof(occ->'lineIndex') IS DISTINCT FROM 'number' OR (occ->>'lineIndex'~'^[0-9]+$') IS NOT TRUE\n   THEN RAISE EXCEPTION 'prodat_object_batch_ignored_field_physical_scope_invalid';END IF;\n  SELECT x INTO physical FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN'\n   AND (SELECT count(*) FROM jsonb_array_elements(tokens)prior WHERE prior->>'tag'='LIN' AND (prior->>'index')::int<(x->>'index')::int)=(occ->>'lineIndex')::int;\n  SELECT o,r INTO owner_object,owner_register FROM jsonb_array_elements(application->'objects')o CROSS JOIN LATERAL jsonb_array_elements(o->'registers')r\n   WHERE o->>'objectId'=occ->>'objectId' AND o->>'identityAgency'=occ->>'identityAgency' AND o->>'messageReference'=occ->>'messageReference' AND r->'lineIndex'=occ->'lineIndex';\n  IF physical IS NULL OR owner_object IS NULL OR physical#>>'{elements,1,0}' IS DISTINCT FROM occ->>'lineNumber'\n   OR physical#>>'{elements,3,0}' IS DISTINCT FROM occ->>'objectId' OR physical#>>'{elements,3,3}' IS DISTINCT FROM occ->>'identityAgency'\n   OR owner_register->'segmentIndex' IS DISTINCT FROM physical->'index' OR owner_register->'lineNumber' IS DISTINCT FROM occ->'lineNumber'\n   OR owner_register->'registerPosition' IS DISTINCT FROM occ->'registerPosition'\n   THEN RAISE EXCEPTION 'prodat_object_batch_ignored_field_physical_scope_invalid';END IF;\n  first_owner_index:=(owner_object#>>'{registers,0,segmentIndex}')::int;\n  SELECT min((x->>'index')::int) INTO first_owner_end FROM jsonb_array_elements(tokens)x WHERE x->>'tag' IN('LIN','UNT') AND(x->>'index')::int>first_owner_index;\n  SELECT min((x->>'index')::int) INTO first_party_index FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND(x->>'index')::int>first_owner_index AND(x->>'index')::int<first_owner_end;\n  SELECT count(*),min(nullif(x#>>'{elements,1,1}','')) INTO li_count,li FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI'\n   AND(x->>'index')::int>first_owner_index AND(x->>'index')::int<coalesce(first_party_index,first_owner_end);\n  SELECT count(*),min(nullif(x#>>'{elements,2,0}','')) INTO customer_count,customer_ref FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='UD'\n   AND(x->>'index')::int>first_owner_index AND(x->>'index')::int<first_owner_end;\n  refs:=jsonb_build_object('objectId',jsonb_build_object('kind','present','value',owner_object->>'objectId'),\n   'lineItemReference',CASE WHEN li_count>1 THEN jsonb_build_object('kind','unavailable') WHEN li IS NULL THEN jsonb_build_object('kind','absent') ELSE jsonb_build_object('kind','present','value',li) END,\n   'customerId',CASE WHEN customer_count>1 THEN jsonb_build_object('kind','unavailable') WHEN customer_ref IS NULL THEN jsonb_build_object('kind','absent') ELSE jsonb_build_object('kind','present','value',customer_ref) END);\n  IF occ->>'lineItemReference' IS DISTINCT FROM (CASE WHEN li_count=1 THEN li END)\n   OR occ ? 'ownReferences' AND occ->'ownReferences' IS DISTINCT FROM refs\n   THEN RAISE EXCEPTION 'prodat_object_batch_ignored_field_physical_scope_invalid';END IF;\n  -- Valid other-object/register entries are nonmatching, never global errors.\n  IF owner_object=own AND occ->'lineIndex'=own#>'{registers,0,lineIndex}' AND (physical->>'index')::int=first_index THEN\n   own_fields:=array_append(own_fields,field->>'fieldNumber');\n  END IF;\n END LOOP;\n -- Consume canonical decisions without another subtype classifier.\n IF '213'=ANY(own_fields) THEN qty:=NULL;END IF;\n IF '222'=ANY(own_fields) THEN frequency:=NULL;END IF;\n IF '242'=ANY(own_fields) THEN product:=NULL;END IF;\n IF 'END_USER_GROUP'=ANY(own_fields) THEN ud:=NULL;\n ELSE\n  IF '227'=ANY(own_fields) THEN ud:=jsonb_set(ud,'{2}','[]'::jsonb);END IF;\n  IF '228'=ANY(own_fields) THEN ud:=jsonb_set(ud,'{4}','[]'::jsonb);END IF;\n END IF;\n IF 'INSTALLATION_GROUP'=ANY(own_fields) THEN it:=NULL;\n ELSE\n  IF '234'=ANY(own_fields) THEN it:=jsonb_set(it,'{5}','[]'::jsonb);END IF;\n  IF '235'=ANY(own_fields) THEN it:=jsonb_set(it,'{8}','[]'::jsonb);END IF;\n  IF '236'=ANY(own_fields) THEN it:=jsonb_set(it,'{6}','[]'::jsonb);END IF;\n  IF '237'=ANY(own_fields) THEN it:=jsonb_set(it,'{9}','[]'::jsonb);END IF;\n END IF;\n IF '319'=ANY(own_fields) THEN reference:=NULL;END IF;\n IF area IS NOT NULL THEN SELECT id INTO grid_id FROM public.grid_owners WHERE company_id=(command->>'company_id')::uuid AND owner_code=area FOR SHARE;\n  IF (SELECT count(*) FROM public.grid_owners WHERE company_id=(command->>'company_id')::uuid AND owner_code=area)>1 THEN RAISE EXCEPTION 'prodat_object_batch_grid_namespace_ambiguous';END IF;END IF;\n IF command#>'{site,grid_owner_id}' IS NOT NULL AND command#>'{site,grid_owner_id}' IS DISTINCT FROM coalesce(to_jsonb(grid_id::text),'null'::jsonb) OR command#>'{metering_point,grid_owner_id}' IS NOT NULL AND command#>'{metering_point,grid_owner_id}' IS DISTINCT FROM coalesce(to_jsonb(grid_id::text),'null'::jsonb) THEN RAISE EXCEPTION 'prodat_object_batch_wire_grid_owner_required';END IF;\n SELECT string_agg(btrim(v#>>'{}'),E'\\n' ORDER BY ord) INTO name FROM jsonb_array_elements(coalesce(ud->4,'[]')) WITH ORDINALITY n(v,ord) WHERE ord<=2 AND btrim(v#>>'{}')<>'';\n is_business:=ud#>>'{2,1}'='SE1';\n IF ud#>>'{2,0}'~'^[0-9]+([-+][0-9]+)?$' THEN\n  IF ud#>>'{2,1}'='SE1' THEN org:=regexp_replace(ud#>>'{2,0}','[^0-9]','','g');ELSIF ud#>>'{2,1}'='SE2' THEN personal:=regexp_replace(ud#>>'{2,0}','[^0-9]','','g');END IF;\n END IF;\n expected:=jsonb_build_object('customer_type',CASE WHEN is_business THEN 'business' ELSE 'private' END,'full_name',coalesce(name,'Ediel inbound-kund'),'company_name',CASE WHEN is_business THEN name END,\n  'first_name',CASE WHEN NOT coalesce(is_business,false) THEN split_part(name,' ',1) END,'last_name',CASE WHEN NOT coalesce(is_business,false) THEN nullif(substr(name,strpos(name,' ')+1),name) END,'personal_number',personal,'org_number',org);\n FOR key,field_value IN SELECT * FROM jsonb_each(command->'customer') LOOP\n  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_customer_required';END IF;\n  IF NOT(expected ? key) AND key NOT IN('status','source','metadata','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_customer_field_not_source_bound';END IF;\n  IF key='status' AND field_value IS DISTINCT FROM '\"draft\"'::jsonb OR key='source' AND field_value IS DISTINCT FROM '\"ediel_inbound\"'::jsonb THEN RAISE EXCEPTION 'prodat_object_batch_customer_binding_required';END IF;\n  IF key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;\n END LOOP;\n expected:=jsonb_build_object('site_name','Ediel '||(own->>'objectId'),'facility_id',own->>'objectId','site_type',CASE WHEN product='L641Q' THEN 'production' ELSE 'consumption' END,\n  'street',CASE WHEN it IS NOT NULL AND NOT('234'=ANY(own_fields)) THEN array_to_string(ARRAY(SELECT btrim(v#>>'{}') FROM jsonb_array_elements(it->5) WITH ORDINALITY a(v,ord) WHERE ord<=3 AND btrim(v#>>'{}')<>''),E'\\n') END,\n  'postal_code',nullif(it#>>'{8,0}',''),'city',nullif(it#>>'{6,0}',''),'country',coalesce(nullif(it#>>'{9,0}',''),'SE'),\n  'annual_consumption_kwh',CASE WHEN qty IS NOT NULL THEN replace(qty,',','.')::numeric END,'move_in_date',CASE WHEN start_day IS NOT NULL THEN substr(start_day,1,4)||'-'||substr(start_day,5,2)||'-'||substr(start_day,7,2) END);\n FOR key,field_value IN SELECT * FROM jsonb_each(command->'site') LOOP\n  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_site_required';END IF;\n  IF key='status' AND field_value IS DISTINCT FROM '\"draft\"'::jsonb OR key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;\n  IF NOT(expected ? key) AND key NOT IN('status','grid_owner_id','internal_notes','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_site_field_not_source_bound';END IF;\n END LOOP;\n expected:=jsonb_build_object('meter_point_id',own->>'objectId','metering_point_id',own->>'objectId','site_facility_id',own->>'objectId','ediel_reference',reference,\n  'measurement_type',CASE WHEN product='L641Q' THEN 'production' ELSE 'consumption' END,'reading_frequency',CASE frequency WHEN 'D' THEN 'daily' WHEN 'M' THEN 'monthly' ELSE 'hourly' END,\n  'start_date',CASE WHEN start_day IS NOT NULL THEN substr(start_day,1,4)||'-'||substr(start_day,5,2)||'-'||substr(start_day,7,2) END,'is_settlement_relevant',true);\n FOR key,field_value IN SELECT * FROM jsonb_each(command->'metering_point') LOOP\n  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_meter_required';END IF;\n  IF key='status' AND field_value IS DISTINCT FROM '\"draft\"'::jsonb OR key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;\n  IF NOT(expected ? key) AND key NOT IN('status','grid_owner_id','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_meter_field_not_source_bound';END IF;\n END LOOP;\nEND $_$;"},"tables":{"gridex_ediel_retention.decision_evidence_catalog":"CREATE TABLE gridex_ediel_retention.decision_evidence_catalog (\n    retention_class text NOT NULL,\n    source_table text NOT NULL,\n    permission_key text NOT NULL,\n    revocation_table text NOT NULL,\n    revocation_id_column text NOT NULL,\n    receipt_function text NOT NULL\n);","gridex_ediel_retention.decision_evidence_policies":"CREATE TABLE gridex_ediel_retention.decision_evidence_policies (\n    id uuid DEFAULT gen_random_uuid() NOT NULL,\n    company_id uuid NOT NULL,\n    retention_class text NOT NULL,\n    target_id uuid NOT NULL,\n    source_hash text NOT NULL,\n    target_metadata_hash text NOT NULL,\n    document_bytes bytea,\n    document_hash text NOT NULL,\n    document_byte_length bigint,\n    document_purged_at timestamp with time zone,\n    issuer_receipt jsonb,\n    submitted_by uuid NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,\n    CONSTRAINT decision_evidence_policies_check CHECK ((target_id <> id)),\n    CONSTRAINT decision_evidence_policies_check1 CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0)))),\n    CONSTRAINT decision_evidence_policies_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),\n    CONSTRAINT decision_evidence_policies_document_hash_check CHECK ((document_hash ~ '^[a-f0-9]{64}$'::text)),\n    CONSTRAINT decision_evidence_policies_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text)),\n    CONSTRAINT decision_evidence_policies_target_metadata_hash_check CHECK ((target_metadata_hash ~ '^[a-f0-9]{64}$'::text))\n);","gridex_ediel_retention.decision_evidence_reviews":"CREATE TABLE gridex_ediel_retention.decision_evidence_reviews (\n    id uuid DEFAULT gen_random_uuid() NOT NULL,\n    policy_id uuid NOT NULL,\n    actor_user_id uuid NOT NULL,\n    outcome text NOT NULL,\n    reason text NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,\n    CONSTRAINT decision_evidence_reviews_outcome_check CHECK ((outcome = ANY (ARRAY['approved'::text, 'held'::text, 'rejected'::text]))),\n    CONSTRAINT decision_evidence_reviews_reason_check CHECK (((length(reason) >= 1) AND (length(reason) <= 4000)))\n);","gridex_ediel_retention.decision_evidence_revocations":"CREATE TABLE gridex_ediel_retention.decision_evidence_revocations (\n    policy_id uuid NOT NULL,\n    actor_user_id uuid NOT NULL,\n    reason text NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,\n    CONSTRAINT decision_evidence_revocations_reason_check CHECK (((length(reason) >= 1) AND (length(reason) <= 4000)))\n);","gridex_ediel_retention.decision_evidence_tombstones":"CREATE TABLE gridex_ediel_retention.decision_evidence_tombstones (\n    retention_class text NOT NULL,\n    target_id uuid NOT NULL,\n    company_id uuid NOT NULL,\n    policy_id uuid NOT NULL,\n    review_id uuid NOT NULL,\n    source_hash text NOT NULL,\n    target_metadata_hash text NOT NULL,\n    byte_length bigint NOT NULL,\n    actor_user_id uuid NOT NULL,\n    journal_retain_until timestamp with time zone NOT NULL,\n    journal_purpose_reference text NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,\n    CONSTRAINT decision_evidence_tombstones_byte_length_check CHECK ((byte_length > 0))\n);","gridex_ediel_retention.issuers":"CREATE TABLE gridex_ediel_retention.issuers (\n    id uuid DEFAULT gen_random_uuid() NOT NULL,\n    company_id uuid NOT NULL,\n    legal_reference text NOT NULL,\n    legal_evidence bytea NOT NULL,\n    legal_hash text NOT NULL,\n    signing_key bytea NOT NULL,\n    valid_from timestamp with time zone NOT NULL,\n    valid_to timestamp with time zone NOT NULL,\n    CONSTRAINT issuers_check CHECK ((legal_hash = encode(sha256(legal_evidence), 'hex'::text))),\n    CONSTRAINT issuers_check1 CHECK ((isfinite(valid_from) AND isfinite(valid_to) AND (valid_to > valid_from))),\n    CONSTRAINT issuers_legal_evidence_check CHECK ((octet_length(legal_evidence) > 0)),\n    CONSTRAINT issuers_legal_reference_check CHECK ((length(legal_reference) > 0)),\n    CONSTRAINT issuers_signing_key_check CHECK ((octet_length(signing_key) >= 32))\n);","gridex_ediel_retention.issuer_revocations":"CREATE TABLE gridex_ediel_retention.issuer_revocations (\n    issuer_id uuid NOT NULL,\n    reference text NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,\n    CONSTRAINT issuer_revocations_reference_check CHECK ((length(reference) > 0))\n);","gridex_ediel_retention.blob_decisions":"CREATE TABLE gridex_ediel_retention.blob_decisions (\n    id uuid DEFAULT gen_random_uuid() NOT NULL,\n    company_id uuid NOT NULL,\n    retention_class text NOT NULL,\n    target_id uuid NOT NULL,\n    message_id uuid NOT NULL,\n    source_hash text NOT NULL,\n    target_hash text NOT NULL,\n    document_bytes bytea,\n    document_hash text NOT NULL,\n    issuer_receipt jsonb,\n    submitted_by uuid NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,\n    document_byte_length bigint,\n    document_purged_at timestamp with time zone,\n    CONSTRAINT blob_decisions_check CHECK ((document_hash = encode(sha256(document_bytes), 'hex'::text))),\n    CONSTRAINT blob_decisions_document_bytes_check CHECK (((octet_length(document_bytes) >= 1) AND (octet_length(document_bytes) <= 1048576))),\n    CONSTRAINT blob_decisions_retention_class_check CHECK ((retention_class = ANY (ARRAY['received_ediel_message_content'::text, 'transport_raw_mime_bytes'::text]))),\n    CONSTRAINT decision_original_byte_custody CHECK ((((document_bytes IS NOT NULL) AND (document_purged_at IS NULL)) OR ((document_bytes IS NULL) AND (document_purged_at IS NOT NULL) AND (document_byte_length > 0))))\n);","gridex_ediel_retention.blob_revocations":"CREATE TABLE gridex_ediel_retention.blob_revocations (\n    decision_id uuid NOT NULL,\n    actor_user_id uuid NOT NULL,\n    reason text NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL\n);","gridex_ediel_retention.classification_copy_revocations":"CREATE TABLE gridex_ediel_retention.classification_copy_revocations (\n    retention_class text NOT NULL,\n    classification_id uuid NOT NULL,\n    company_id uuid NOT NULL,\n    source_message_id uuid NOT NULL,\n    policy_id uuid NOT NULL,\n    review_id uuid NOT NULL,\n    source_hash text NOT NULL,\n    actor_user_id uuid NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,\n    CONSTRAINT classification_copy_revocations_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text))\n);","gridex_ediel_retention.contract_copy_revocations":"CREATE TABLE gridex_ediel_retention.contract_copy_revocations (\n    retention_class text NOT NULL,\n    target_id uuid NOT NULL,\n    company_id uuid NOT NULL,\n    policy_id uuid NOT NULL,\n    review_id uuid NOT NULL,\n    source_hash text NOT NULL,\n    actor_user_id uuid NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,\n    CONSTRAINT contract_copy_revocations_source_hash_check CHECK ((source_hash ~ '^[a-f0-9]{64}$'::text))\n);","gridex_ediel_retention.protected_copy_revocations":"CREATE TABLE gridex_ediel_retention.protected_copy_revocations (\n    retention_class text NOT NULL,\n    target_id uuid NOT NULL,\n    company_id uuid NOT NULL,\n    policy_id uuid NOT NULL,\n    review_id uuid NOT NULL,\n    source_hash text NOT NULL,\n    actor_user_id uuid NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL\n);","gridex_ediel_retention.protected_copy_specs":"CREATE TABLE gridex_ediel_retention.protected_copy_specs (\n    retention_class text NOT NULL,\n    view_name text NOT NULL,\n    source_schema text NOT NULL,\n    source_table text NOT NULL,\n    body_field text NOT NULL,\n    hash_field text NOT NULL\n);","gridex_ediel_retention.record_class_catalog":"CREATE TABLE gridex_ediel_retention.record_class_catalog (\n    retention_class text NOT NULL,\n    source_table text NOT NULL,\n    permission_key text NOT NULL,\n    operation text NOT NULL,\n    redaction jsonb NOT NULL,\n    CONSTRAINT record_class_catalog_redaction_check CHECK ((jsonb_typeof(redaction) = 'object'::text))\n);","public.permissions":"CREATE TABLE public.permissions (\n    id uuid DEFAULT gen_random_uuid() NOT NULL,\n    key text,\n    name text NOT NULL,\n    description text,\n    category text,\n    is_active boolean DEFAULT true NOT NULL,\n    created_at timestamp with time zone DEFAULT now() NOT NULL\n);","public.audit_logs":"CREATE TABLE public.audit_logs (\n    id uuid DEFAULT gen_random_uuid() NOT NULL,\n    company_id uuid,\n    actor_user_id uuid,\n    entity_type text NOT NULL,\n    entity_id text NOT NULL,\n    action text NOT NULL,\n    old_values jsonb,\n    new_values jsonb,\n    metadata jsonb,\n    created_at timestamp with time zone DEFAULT now() NOT NULL,\n    updated_at timestamp with time zone DEFAULT now(),\n    actor_type text NOT NULL,\n    system_actor text,\n    request_id text NOT NULL,\n    correlation_id text NOT NULL,\n    resource_type text NOT NULL,\n    resource_id text NOT NULL,\n    previous_status text,\n    new_status text,\n    CONSTRAINT audit_logs_actor_type_check CHECK ((actor_type = ANY (ARRAY['user'::text, 'system'::text]))),\n    CONSTRAINT audit_logs_system_actor_check CHECK (((actor_user_id IS NOT NULL) OR (NULLIF(system_actor, ''::text) IS NOT NULL)))\n);"},"sourceFiles":["20261019180000_db05_completed_decision_review_reason_retention.sql","20261019180100_db05_completed_review_witness_consumer_freeze.sql","20261019180200_db05_completed_witness_field_disposition.sql","20261019180300_db05_completed_parent_purpose_disposition.sql","20261019180400_db05_qualified_audit19_cleanup.sql","20261019180500_db05_audit19_archived_permission.sql"],"tableFixtureLimitation":"Exact declared columns/checks from actual source; additional actual PK/RLS/owner/trigger and explicit auth/reference grant seams established in script; no business rows or policy facts seeded.","functionACLStatements":["REVOKE ALL ON FUNCTION gridex_ediel_retention.decision_evidence_basis_v1(c uuid, k text, target uuid) FROM PUBLIC;","REVOKE ALL ON FUNCTION gridex_ediel_retention.decision_evidence_lock_v1(c uuid) FROM PUBLIC;","REVOKE ALL ON FUNCTION gridex_ediel_retention.decision_evidence_policies_original_guard_v1() FROM PUBLIC;","REVOKE ALL ON FUNCTION gridex_ediel_retention.decision_evidence_receipt_v1(d gridex_ediel_retention.decision_evidence_policies) FROM PUBLIC;","REVOKE ALL ON FUNCTION gridex_ediel_retention.decision_evidence_transition_v1(tab text, o jsonb, n jsonb) FROM PUBLIC;","REVOKE ALL ON FUNCTION gridex_ediel_retention.permission_v1(c uuid, actor uuid, wanted text) FROM PUBLIC;","REVOKE ALL ON FUNCTION gridex_prodat_object_batch.require_wire_projection_v1(raw text, own jsonb, command jsonb, mode text, actor uuid) FROM PUBLIC;","REVOKE ALL ON FUNCTION gridex_received_sources.other_supply_scope_effect_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_scope jsonb, p_source_cohort uuid[], p_canonical_id uuid) FROM PUBLIC;","REVOKE ALL ON FUNCTION gridex_received_sources.reject_mutation() FROM PUBLIC;","REVOKE ALL ON FUNCTION public.ediel_current_retention_session_v1(p_company_id uuid, p_actor_user_id uuid) FROM PUBLIC;","GRANT ALL ON FUNCTION public.ediel_current_retention_session_v1(p_company_id uuid, p_actor_user_id uuid) TO authenticated;","REVOKE ALL ON FUNCTION public.ediel_purge_decision_evidence_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_policy_id uuid) FROM PUBLIC;","GRANT ALL ON FUNCTION public.ediel_purge_decision_evidence_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_policy_id uuid) TO authenticated;","REVOKE ALL ON FUNCTION public.ediel_read_decision_evidence_policy_v1(p_company_id uuid, p_actor_user_id uuid, p_policy_id uuid, p_include_document boolean) FROM PUBLIC;","GRANT ALL ON FUNCTION public.ediel_read_decision_evidence_policy_v1(p_company_id uuid, p_actor_user_id uuid, p_policy_id uuid, p_include_document boolean) TO authenticated;","REVOKE ALL ON FUNCTION public.ediel_read_retention_decision_original_v1(p_company_id uuid, p_actor_user_id uuid, p_retention_class text, p_target_id uuid, p_include_document boolean) FROM PUBLIC;","GRANT ALL ON FUNCTION public.ediel_read_retention_decision_original_v1(p_company_id uuid, p_actor_user_id uuid, p_retention_class text, p_target_id uuid, p_include_document boolean) TO authenticated;"]}
const root=process.env.GRIDEX_DB05_INSTALL_ROOT??resolve(dirname(fileURLToPath(import.meta.url)),'..')
const useBaseline=process.env.GRIDEX_DB05_INSTALL_BASELINE==='1'
const file=n=>readFileSync(resolve(root,'supabase/migrations',n),'utf8')
const core=s=>s.replace(/\n-- DB05_INSTALL_OWNER_SCOPE_BEGIN[\s\S]*?-- DB05_INSTALL_OWNER_SCOPE_END\n/,'').replace(/-- DB05_INSTALL_OWNER_RESTORE_BEGIN[\s\S]*?-- DB05_INSTALL_OWNER_RESTORE_END\n/,'')
const one=async(db,q)=>(await db.query(q)).rows[0].v
const authoritySQL=`SELECT jsonb_build_object('memberships',(SELECT jsonb_agg(to_jsonb(m) ORDER BY m.oid) FROM pg_auth_members m),'roles',(SELECT jsonb_agg(to_jsonb(r)-'rolpassword' ORDER BY r.oid) FROM pg_roles r),'namespaces',(SELECT jsonb_agg(to_jsonb(n) ORDER BY n.oid) FROM pg_namespace n WHERE n.nspname IN('public','gridex_ediel_retention')),'ownerAuthUsage',has_schema_privilege('gridex_ediel_retention_owner','auth','USAGE')) v`
const businessSQL=`SELECT jsonb_build_object('classes',(SELECT jsonb_agg(to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid'] ORDER BY c.oid) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('public','gridex_ediel_retention')),'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.attrelid,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('public','gridex_ediel_retention')),'functions',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('public','gridex_ediel_retention')),'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('public','gridex_ediel_retention')),'constraints',(SELECT jsonb_agg(to_jsonb(k) ORDER BY k.oid) FROM pg_constraint k JOIN pg_namespace n ON n.oid=k.connamespace WHERE n.nspname IN('public','gridex_ediel_retention')),'permissions',(SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM public.permissions p),'catalog',(SELECT jsonb_agg(to_jsonb(c) ORDER BY retention_class) FROM gridex_ediel_retention.decision_evidence_catalog c)) v`
async function businessSnapshot(db){
 // Separate fixture-admin observation only: installer always runs as real postgres.
 await db.exec('SET SESSION AUTHORIZATION supabase_admin');
 try{return await one(db,businessSQL)}finally{await db.exec('SET SESSION AUTHORIZATION postgres')}
}
async function identity(db){
 const r=(await db.query(`SELECT current_user c,session_user s,rolsuper,rolbypassrls,rolcreaterole,pg_has_role('postgres','gridex_ediel_retention_owner','USAGE') inherited,pg_has_role('postgres','gridex_ediel_retention_owner','SET') can_set,current_setting('check_function_bodies') checked FROM pg_roles WHERE rolname=current_user`)).rows[0]
 assert.deepEqual(r,{c:'postgres',s:'postgres',rolsuper:false,rolbypassrls:true,rolcreaterole:true,inherited:false,can_set:true,checked:'on'})
 const profile=await one(db,`SELECT jsonb_agg(jsonb_build_array(g.rolname,m.admin_option,m.inherit_option,m.set_option) ORDER BY g.rolname COLLATE "C") v FROM pg_auth_members m JOIN pg_roles g ON g.oid=m.grantor WHERE roleid='gridex_ediel_retention_owner'::regrole AND member='postgres'::regrole`)
 assert.deepEqual(profile,[['postgres',false,false,true],['supabase_admin',true,false,false]])
}
async function setup(){
 const db=new PGlite()
 // PGlite bootstrap OID10 must stay superuser. Name it exactly as the genuine
 // Supabase bootstrap principal; create a separate actual NOSUPER postgres.
 await db.exec(`CREATE ROLE fixture_setup_admin LOGIN SUPERUSER;SET SESSION AUTHORIZATION fixture_setup_admin;ALTER ROLE postgres RENAME TO supabase_admin;SET SESSION AUTHORIZATION supabase_admin;CREATE ROLE postgres LOGIN NOSUPERUSER INHERIT CREATEROLE BYPASSRLS;CREATE ROLE gridex_ediel_retention_owner NOLOGIN NOINHERIT BYPASSRLS;CREATE ROLE anon;CREATE ROLE authenticated;CREATE ROLE service_role;CREATE ROLE fixture_other;ALTER DATABASE postgres OWNER TO postgres;ALTER SCHEMA public OWNER TO postgres;CREATE SCHEMA auth AUTHORIZATION supabase_admin;CREATE TABLE auth.users(id uuid PRIMARY KEY);GRANT USAGE ON SCHEMA auth TO postgres;GRANT SELECT,UPDATE,REFERENCES ON auth.users TO postgres;CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT NULL::uuid$$;CREATE SCHEMA gridex_ediel_retention AUTHORIZATION gridex_ediel_retention_owner;GRANT USAGE ON SCHEMA gridex_ediel_retention TO postgres;CREATE SCHEMA gridex_received_sources AUTHORIZATION postgres;CREATE SCHEMA gridex_requested_changes AUTHORIZATION postgres;CREATE SCHEMA gridex_prodat_object_batch AUTHORIZATION postgres;CREATE SCHEMA gridex_ediel_ack_replay AUTHORIZATION postgres;CREATE TABLE public.companies(id uuid PRIMARY KEY);CREATE TABLE public.customers(id uuid PRIMARY KEY,company_id uuid,legal_hold boolean);CREATE TABLE public.ediel_messages(id uuid PRIMARY KEY,company_id uuid,customer_id uuid);CREATE TABLE public.ediel_message_payloads(id uuid PRIMARY KEY,company_id uuid,ediel_message_id uuid);`)
 for(const name of ['companies','customers','ediel_messages','ediel_message_payloads'])await db.exec(`ALTER TABLE public.${name} OWNER TO postgres`)
 for(const [name,ddl] of Object.entries(baseline.tables)){
  await db.exec(ddl)
  await db.exec(`ALTER TABLE ${name} OWNER TO ${name.startsWith('gridex_ediel_retention.')?'gridex_ediel_retention_owner':'postgres'}`)
 }
 await db.exec(`ALTER TABLE gridex_ediel_retention.decision_evidence_catalog ADD PRIMARY KEY(retention_class);ALTER TABLE gridex_ediel_retention.decision_evidence_catalog ADD UNIQUE(source_table);ALTER TABLE gridex_ediel_retention.decision_evidence_catalog ADD UNIQUE(permission_key);ALTER TABLE gridex_ediel_retention.decision_evidence_policies ADD PRIMARY KEY(id);ALTER TABLE gridex_ediel_retention.decision_evidence_reviews ADD PRIMARY KEY(id);ALTER TABLE gridex_ediel_retention.decision_evidence_revocations ADD PRIMARY KEY(policy_id);ALTER TABLE gridex_ediel_retention.decision_evidence_tombstones ADD PRIMARY KEY(retention_class,target_id);ALTER TABLE public.permissions ADD PRIMARY KEY(id);ALTER TABLE public.permissions ADD UNIQUE(key);ALTER TABLE public.audit_logs ADD PRIMARY KEY(id);`)
 for(const name of Object.keys(baseline.tables).filter(x=>x.startsWith('gridex_ediel_retention.')))await db.exec(`ALTER TABLE ${name} ENABLE ROW LEVEL SECURITY;ALTER TABLE ${name} FORCE ROW LEVEL SECURITY;REVOKE ALL ON ${name} FROM PUBLIC,anon,authenticated,service_role`)
 // Baseline declarations contain exact genuine bodies with uncalled external
 // graph ports. Only declaration validation is disabled in this GIVEN setup;
 // restore it before any actual candidate installer is executed.
 await db.exec('SET check_function_bodies=off')
 for(const [name,definition] of Object.entries(baseline.functions)){
  await db.exec(definition)
  await db.exec(`ALTER FUNCTION ${name}(${(await db.query(`SELECT pg_get_function_identity_arguments(p.oid) args FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=$1`,[name])).rows[0].args}) OWNER TO ${name.startsWith('gridex_ediel_retention.')||name.startsWith('public.ediel_')?'gridex_ediel_retention_owner':'postgres'}`)
 }
 await db.exec('SET check_function_bodies=on')
 // Actual source ACL declarations, not default PUBLIC function EXECUTE.
 for(const sql of baseline.functionACLStatements)await db.exec(sql)
 for(const name of ['decision_evidence_policies','decision_evidence_reviews','decision_evidence_revocations','decision_evidence_tombstones'])await db.exec(`CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON gridex_ediel_retention.${name} FOR EACH ROW EXECUTE FUNCTION ${name==='decision_evidence_policies'?'gridex_ediel_retention.decision_evidence_policies_original_guard_v1':'gridex_received_sources.reject_mutation'}()`)
 await db.exec(`INSERT INTO gridex_ediel_retention.decision_evidence_catalog VALUES('blob_retention_decision_original_bytes','blob_decisions','ediel.retention.blob_decision_evidence','blob_revocations','decision_id','blob_receipt_v1'),('decision_evidence_policy_original_bytes','decision_evidence_policies','ediel.retention.decision_policy_evidence','decision_evidence_revocations','policy_id','decision_evidence_policy_current_v1');GRANT INSERT ON public.audit_logs TO gridex_ediel_retention_owner;GRANT SELECT,UPDATE ON public.permissions TO gridex_ediel_retention_owner;GRANT gridex_ediel_retention_owner TO postgres WITH ADMIN TRUE,INHERIT FALSE,SET FALSE GRANTED BY supabase_admin;SET SESSION AUTHORIZATION postgres;GRANT gridex_ediel_retention_owner TO postgres WITH ADMIN FALSE,INHERIT FALSE,SET TRUE GRANTED BY postgres;`)
 await identity(db);assert.equal(await one(db,"SELECT has_schema_privilege('gridex_ediel_retention_owner','auth','USAGE') v"),false)
 return db
}
async function rejected(db,sql,pattern){
 try{await db.exec(sql);assert.fail('expected actual SQL refusal')}catch(e){assert.match(e.message,pattern);await db.exec('ROLLBACK')}
}
async function withDb(fn){const db=await setup();try{await fn(db)}finally{await db.close()}}
// One identical positive oracle supplies genuine semantic RED with original
