test('actual NOSUPERUSER/NOINHERIT postgres installs all six genuine forwards and restores authority at each COMMIT',async()=>withDb(async db=>{
 const before=await one(db,authoritySQL)
 for(const name of baseline.sourceFiles){
  await identity(db)
  const sql=useBaseline?core(file(name)):file(name)
  try{await db.exec(sql)}catch(e){console.error(JSON.stringify({migration:name,message:e.message,where:e.where,detail:e.detail}));throw e}
  assert.deepEqual(await one(db,authoritySQL),before,'authority/catalog restore after '+name)
  await identity(db)
 }
 assert.equal(await one(db,"SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') v FROM pg_proc WHERE oid='gridex_ediel_retention.permission_v1(uuid,uuid,text)'::regprocedure"),'b4027dcae1ce6e709fd37afb329589649197104c801aeb4110454a60045cc0fa')
 const acl=await one(db,"SELECT jsonb_build_object('read',has_table_privilege('gridex_ediel_retention_owner','public.audit_logs','SELECT'),'erase',has_table_privilege('gridex_ediel_retention_owner','public.audit_logs','DELETE'),'lockColumn',has_column_privilege('gridex_ediel_retention_owner','public.audit_logs','id','UPDATE'),'otherUpdate',has_column_privilege('gridex_ediel_retention_owner','public.audit_logs','updated_at','UPDATE'),'ownerAuthUsage',has_schema_privilege('gridex_ediel_retention_owner','auth','USAGE')) v")
 assert.deepEqual(acl,{read:true,erase:true,lockColumn:true,otherUpdate:false,ownerAuthUsage:false})
}))
